package org.jsoup.safety;

/*
    Thank you to Ryan Grove (wonko.com) for the Ruby HTML cleaner http://github.com/rgrove/sanitize/, which inspired
    this safe-list configuration, and the initial defaults.
 */

import org.jsoup.helper.Validate;
import org.jsoup.internal.Normalizer;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;

import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;
import java.util.HashMap;

import static org.jsoup.internal.Normalizer.lowerCase;


/**
 Safelists define what HTML (elements and attributes) to allow through a {@link Cleaner}. Everything else is removed.
 <p>
 Start with one of the defaults:
 </p>
 <ul>
 <li>{@link #none}
 <li>{@link #simpleText}
 <li>{@link #basic}
 <li>{@link #basicWithImages}
 <li>{@link #relaxed}
 </ul>
 <p>
 If you need to allow more through (please be careful!), tweak a base safelist with:
 </p>
 <ul>
 <li>{@link #addTags(String... tagNames)}
 <li>{@link #addAttributes(String tagName, String... attributes)}
 <li>{@link #addEnforcedAttribute(String tagName, String attribute, String value)}
 <li>{@link #addProtocols(String tagName, String attribute, String... protocols)}
 </ul>
 <p>
 You can remove any setting from an existing safelist with:
 </p>
 <ul>
 <li>{@link #removeTags(String... tagNames)}
 <li>{@link #removeAttributes(String tagName, String... attributes)}
 <li>{@link #removeEnforcedAttribute(String tagName, String attribute)}
 <li>{@link #removeProtocols(String tagName, String attribute, String... removeProtocols)}
 </ul>

 <p>
 The {@link Cleaner} and these safelists assume that you want to clean a <code>body</code> fragment of HTML (to add user
 supplied HTML into a templated page), and not to clean a full HTML document. If the latter is the case, you could wrap
 the templated document HTML around the cleaned body HTML.
 </p>
 <p>
 Safelists are mutable. A {@link Cleaner} uses the supplied safelist directly, so later changes affect later cleaning
 calls. If you want to share a safelist across threads, finish configuring it first and do not mutate it while it is in
 use. To build a variant from an existing configuration, use {@link #Safelist(Safelist)} to make a copy.
 </p>
 <p>
 If you are going to extend a safelist, please be very careful. Make sure you understand what attributes may lead to
 XSS attack vectors. URL attributes are particularly vulnerable and require careful validation. See 
 the <a href="https://owasp.org/www-community/xss-filter-evasion-cheatsheet">XSS Filter Evasion Cheat Sheet</a> for some
 XSS attack examples (that jsoup will safeguard against with the default Cleaner and Safelist configuration).
 </p>
 */
public class Safelist {
    private static final String All = ":all";
    private static final TagName AllTag = TagName.valueOf(All);
    final SafelistEnforcedAttributes enforcedAttributesManager; // moved enforcement map
    final SafelistProtocols protocolsManager; // moved protocols to dedicated manager
    final SafelistTagAttributes tagAttributes; // encapsulated tag/attribute config
    private boolean preserveRelativeLinks; // option to preserve relative links

    /**
     This safelist allows only text nodes: any HTML Element or any Node other than a TextNode will be removed.
     <p>
     Note that the output of {@link org.jsoup.Jsoup#clean(String, Safelist)} is still <b>HTML</b> even when using
     this Safelist, and so any HTML entities in the output will be appropriately escaped. If you want plain text, not
     HTML, you should use a text method such as {@link Element#text()} instead, after cleaning the document.
     </p>
     <p>Example:</p>
     <pre>{@code
     String sourceBodyHtml = "<p>5 is &lt; 6.</p>";
     String html = Jsoup.clean(sourceBodyHtml, Safelist.none());

     Cleaner cleaner = new Cleaner(Safelist.none());
     String text = cleaner.clean(Jsoup.parse(sourceBodyHtml)).text();

     // html is: 5 is &lt; 6.
     // text is: 5 is < 6.
     }</pre>

     @return safelist
     */
    public static Safelist none() {
        return new Safelist();
    }

    /**
     This safelist allows only simple text formatting: <code>b, em, i, strong, u</code>. All other HTML (tags and
     attributes) will be removed.

     @return safelist
     */
    public static Safelist simpleText() {
        Safelist s = new Safelist();
        s.tagAttributes.addTags("b", "em", "i", "strong", "u");
        return s;
    }

    /**
     <p>
     This safelist allows a fuller range of text nodes: <code>a, b, blockquote, br, cite, code, dd, dl, dt, em, i, li,
     ol, p, pre, q, small, span, strike, strong, sub, sup, u, ul</code>, and appropriate attributes.
     </p>
     <p>
     Links (<code>a</code> elements) can point to <code>http, https, ftp, mailto</code>, and have an enforced
     <code>rel=nofollow</code> attribute if they link offsite (as indicated by the specified base URI).
     </p>
     <p>
     Does not allow images.
     </p>

     @return safelist
     */
    public static Safelist basic() {
        Safelist s = new Safelist();
        s.tagAttributes.addTags(
                "a", "b", "blockquote", "br", "cite", "code", "dd", "dl", "dt", "em",
                "i", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong", "sub",
                "sup", "u", "ul");

        s.tagAttributes.addAttributes("a", "href");
        s.tagAttributes.addAttributes("blockquote", "cite");
        s.tagAttributes.addAttributes("q", "cite");

        s.protocolsManager.addProtocols("a", "href", "ftp", "http", "https", "mailto");
        s.protocolsManager.addProtocols("blockquote", "cite", "http", "https");
        s.protocolsManager.addProtocols("cite", "cite", "http", "https");

        s.enforcedAttributesManager.addEnforcedAttribute("a", "rel", "nofollow"); // has special handling for external links, in Cleaner
        return s;

    }

    /**
     This safelist allows the same text tags as {@link #basic}, and also allows <code>img</code> tags, with appropriate
     attributes, with <code>src</code> pointing to <code>http</code> or <code>https</code>.

     @return safelist
     */
    public static Safelist basicWithImages() {
        Safelist s = basic();
        s.tagAttributes.addTags("img");
        s.tagAttributes.addAttributes("img", "align", "alt", "height", "src", "title", "width");
        s.protocolsManager.addProtocols("img", "src", "http", "https");
        return s;
    }

    /**
     This safelist allows a full range of text and structural body HTML: <code>a, b, blockquote, br, caption, cite,
     code, col, colgroup, dd, div, dl, dt, em, h1, h2, h3, h4, h5, h6, i, img, li, ol, p, pre, q, small, span, strike, strong, sub,
     sup, table, tbody, td, tfoot, th, thead, tr, u, ul</code>
     <p>
     Links do not have an enforced <code>rel=nofollow</code> attribute, but you can add that if desired.
     </p>

     @return safelist
     */
    public static Safelist relaxed() {
        Safelist s = new Safelist();
        s.tagAttributes.addTags(
                "a", "b", "blockquote", "br", "caption", "cite", "code", "col",
                "colgroup", "dd", "div", "dl", "dt", "em", "h1", "h2", "h3", "h4", "h5", "h6",
                "i", "img", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong",
                "sub", "sup", "table", "tbody", "td", "tfoot", "th", "thead", "tr", "u",
                "ul");

        s.tagAttributes.addAttributes("a", "href", "title");
        s.tagAttributes.addAttributes("blockquote", "cite");
        s.tagAttributes.addAttributes("col", "span", "width");
        s.tagAttributes.addAttributes("colgroup", "span", "width");
        s.tagAttributes.addAttributes("img", "align", "alt", "height", "src", "title", "width");
        s.tagAttributes.addAttributes("ol", "start", "type");
        s.tagAttributes.addAttributes("q", "cite");
        s.tagAttributes.addAttributes("table", "summary", "width");
        s.tagAttributes.addAttributes("td", "abbr", "axis", "colspan", "rowspan", "width");
        s.tagAttributes.addAttributes(
                "th", "abbr", "axis", "colspan", "rowspan", "scope",
                "width");
        s.tagAttributes.addAttributes("ul", "type");

        s.protocolsManager.addProtocols("a", "href", "ftp", "http", "https", "mailto");
        s.protocolsManager.addProtocols("blockquote", "cite", "http", "https");
        s.protocolsManager.addProtocols("cite", "cite", "http", "https");
        s.protocolsManager.addProtocols("img", "src", "http", "https");
        s.protocolsManager.addProtocols("q", "cite", "http", "https");
        return s;
    }

    /**
     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.

     @see #basic()
     @see #basicWithImages()
     @see #simpleText()
     @see #relaxed()
     */
    public Safelist() {
        enforcedAttributesManager = new SafelistEnforcedAttributes();
        protocolsManager = new SafelistProtocols();
        tagAttributes = new SafelistTagAttributes(enforcedAttributesManager, protocolsManager);
        preserveRelativeLinks = false;
    }

    /**
     Deep copy an existing Safelist to a new Safelist.
     @param copy the Safelist to copy
     */
    public Safelist(Safelist copy) {
        this();
        // copy tag & attribute config
        this.tagAttributes.copyFrom(copy.tagAttributes);

        // copy enforced attributes via manager copy behavior: copy entries into this.enforcedAttributesManager
        for (Map.Entry<TagName, Map<AttributeKey, AttributeValue>> enforcedEntry : copy.enforcedAttributesManager.getInternalMap().entrySet()) {
            TagName tag = enforcedEntry.getKey();
            for (Map.Entry<AttributeKey, AttributeValue> attributeEntry : enforcedEntry.getValue().entrySet()) {
                enforcedAttributesManager.addEnforcedAttribute(tag.toString(), attributeEntry.getKey().toString(), attributeEntry.getValue().toString());
            }
        }
        // copy protocols via protocols manager
        for (Map.Entry<TagName, Map<AttributeKey, Set<Protocol>>> entry : copy.protocolsManager.getInternalMap().entrySet()) {
            TagName tag = entry.getKey();
            for (Map.Entry<AttributeKey, Set<Protocol>> attrEntry : entry.getValue().entrySet()) {
                for (Protocol p : attrEntry.getValue()) {
                    this.protocolsManager.addProtocols(tag.toString(), attrEntry.getKey().toString(), p.toString());
                }
            }
        }
        preserveRelativeLinks = copy.preserveRelativeLinks;
    }

    /**
     Add an enforced attribute to a tag. An enforced attribute will always be added to the element. If the element
     already has the attribute set, it will be overridden with this value.
     <p>
     E.g.: <code>addEnforcedAttribute("a", "rel", "nofollow")</code> will make all <code>a</code> tags output as
     <code>&lt;a href="..." rel="nofollow"&gt;</code>
     </p>

     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
     @param attribute   The attribute name
     @param value The enforced attribute value
     @return this (for chaining)
     */
    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
        Validate.notEmpty(tag);
        Validate.notEmpty(attribute);
        Validate.notEmpty(value);

        // keep API for chaining, delegate to manager
        enforcedAttributesManager.addEnforcedAttribute(tag, attribute, value);
        TagName tagName = TagName.valueOf(tag);
        tagAttributes.tagNames.add(tagName);
        return this;
    }

    /**
     Remove a previously configured enforced attribute from a tag.

     @param tag   The tag the enforced attribute is for.
     @param attribute   The attribute name
     @return this (for chaining)
     */
    public Safelist removeEnforcedAttribute(String tag, String attribute) {
        Validate.notEmpty(tag);
        Validate.notEmpty(attribute);

        enforcedAttributesManager.removeEnforcedAttribute(tag, attribute);
        return this;
    }

    /**
     * Configure this Safelist to preserve relative links in an element's URL attribute, or convert them to absolute
     * links. By default, this is <b>false</b>: URLs will be  made absolute (e.g. start with an allowed protocol, like
     * e.g. {@code http://}.
     *
     * @param preserve {@code true} to allow relative links, {@code false} (default) to deny
     * @return this Safelist, for chaining.
     * @see #addProtocols
     */
    public Safelist preserveRelativeLinks(boolean preserve) {
        preserveRelativeLinks = preserve;
        return this;
    }

    /**
     * Get the current setting for preserving relative links.
     * @return {@code true} if relative links are preserved, {@code false} if they are converted to absolute.
     */
    public boolean preserveRelativeLinks() {
        return preserveRelativeLinks;
    }

    /**
     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
     URLs with the defined protocol.
     <p>
     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
     </p>
     <p>
     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
     E.g.: <code>addProtocols("a", "href", "#")</code>
     </p>

     @param tag       Tag the URL protocol is for
     @param attribute       Attribute name
     @param protocols List of valid protocols
     @return this, for chaining
     */
    public Safelist addProtocols(String tag, String attribute, String... protocols) {
        // keep API for chaining, delegate to manager
        protocolsManager.addProtocols(tag, attribute, protocols);
        return this;
    }

    /**
     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
     attribute will allow any protocol.
     <p>
     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
     </p>

     @param tag Tag the URL protocol is for
     @param attribute Attribute name
     @param removeProtocols List of invalid protocols
     @return this, for chaining
     */
    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
        // keep API for chaining, delegate to manager
        protocolsManager.removeProtocols(tag, attribute, removeProtocols);
        return this;
    }

    /**
     * Test if the supplied tag is allowed by this safelist.
     * @param tag test tag
     * @return true if allowed
     */
    public boolean isSafeTag(String tag) {
        return tagAttributes.isSafeTag(tag);
    }

    /**
     * Test if the supplied attribute is allowed by this safelist for this tag.
     * <p>This method does not modify the input element or attribute.</p>
     * @param tagName tag to consider allowing the attribute in
     * @param el element under test, to confirm protocol
     * @param attr attribute under test
     * @return true if allowed
     */
    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
        TagName tag = TagName.valueOf(tagName);
        AttributeKey key = AttributeKey.valueOf(attr.getKey());

        Set<AttributeKey> okSet = tagAttributes.getAllowedAttributes(tag);
        if (okSet != null && okSet.contains(key)) {
            Map<AttributeKey, Set<Protocol>> attrProts = protocolsManager.getProtocolsMap(tag);
            if (attrProts != null) {
                // ok if not defined protocol; otherwise test
                return !attrProts.containsKey(key) || protocolsManager.isSafeProtocol(protocolsManager.getProtocolValue(el, attr), attrProts.get(key));
            } else { // attribute found, no protocols defined for this tag, so OK
                return true;
            }
        }
        Safelist.AttributeValue enforced = enforcedAttributesManager.getEnforcedValue(tag, key);
        if (enforced != null) {
            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
            // if the input already has that exact value, treat it as safe
            return enforced.equals(AttributeValue.valueOf(attr.getValue()));
        }
        // no attributes defined for tag, try :all tag
        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
    }

    /**
     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
     attribute.
     */
    boolean shouldAbsUrl(String tagName, String attrKey) {
        if (preserveRelativeLinks) return false;
        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
    }

    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
        Set<AttributeKey> allowedAttrs = tagAttributes.getAllowedAttributes(tag);
        if (allowedAttrs != null && allowedAttrs.contains(key)) {
            return protocolsManager.hasProtocol(tag, key);
        }

        if (enforcedAttributesManager.hasEnforcedAttribute(tag, key)) return false;

        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
    }

    private static boolean isValidAnchor(String value) {
        return value.startsWith("#") && !value.matches(".*\\s.*");
    }

    /**
     Gets the Attributes that should be enforced for a given tag
     * @param tagName the tag
     * @return the attributes that will be enforced; empty if none are set for the given tag
     */
    public Attributes getEnforcedAttributes(String tagName) {
        return enforcedAttributesManager.getEnforcedAttributes(tagName);
    }

    // named types for config. All just hold strings, but here for my sanity.

    static class TagName extends TypedValue {
        TagName(String value) {
            super(value);
        }

        static TagName valueOf(String value) {
            return new TagName(Normalizer.lowerCase(value));
        }
    }

    static class AttributeKey extends TypedValue {
        AttributeKey(String value) {
            super(value);
        }

        static AttributeKey valueOf(String value) {
            return new AttributeKey(Normalizer.lowerCase(value));
        }
    }

    static class AttributeValue extends TypedValue {
        AttributeValue(String value) {
            super(value);
        }

        static AttributeValue valueOf(String value) {
            return new AttributeValue(value);
        }
    }

    static class Protocol extends TypedValue {
        Protocol(String value) {
            super(value);
        }

        static Protocol valueOf(String value) {
            return new Protocol(value);
        }
    }

    abstract static class TypedValue {
        private final String value;

        TypedValue(String value) {
            Validate.notNull(value);
            this.value = value;
        }

        @Override
        public int hashCode() {
            return value.hashCode();
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            TypedValue other = (TypedValue) obj;
            return java.util.Objects.equals(value, other.value);
        }

        @Override
        public String toString() {
            return value;
        }
    }
}

package org.jsoup.safety;

import org.jsoup.helper.Validate;
import org.jsoup.internal.Normalizer;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;

import static org.jsoup.internal.Normalizer.lowerCase;

/**
 * Encapsulates the tag-and-attribute configuration for a Safelist.
 */
public class SafelistTagAttributes {
    // pseudo tag for all
    private static final String All = ":all";

    final Set<Safelist.TagName> tagNames; // tags allowed, lower case. e.g. [p, br, span]
    final Map<Safelist.TagName, Set<Safelist.AttributeKey>> attributes; // tag -> attribute[]. allowed attributes [href] for a tag.
    private final SafelistEnforcedAttributes enforcedAttributesManager; // reference to owner manager
    private final SafelistProtocols protocolsManager; // reference to owner manager

    SafelistTagAttributes(SafelistEnforcedAttributes enforcedAttributesManager, SafelistProtocols protocolsManager) {
        this.tagNames = new HashSet<>();
        this.attributes = new HashMap<>();
        this.enforcedAttributesManager = enforcedAttributesManager;
        this.protocolsManager = protocolsManager;
    }

    // copy helper for Safelist copy ctor
    void copyFrom(SafelistTagAttributes other) {
        this.tagNames.clear();
        this.tagNames.addAll(other.tagNames);
        this.attributes.clear();
        for (Map.Entry<Safelist.TagName, Set<Safelist.AttributeKey>> e : other.attributes.entrySet()) {
            this.attributes.put(e.getKey(), new HashSet<>(e.getValue()));
        }
    }

    public SafelistTagAttributes addTags(String... tags) {
        Validate.notNull(tags);

        for (String tagName : tags) {
            Validate.notEmpty(tagName);
            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
                    "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
            tagNames.add(Safelist.TagName.valueOf(tagName));
        }
        return this;
    }

    public SafelistTagAttributes removeTags(String... tags) {
        Validate.notNull(tags);

        for(String tag: tags) {
            Validate.notEmpty(tag);
            Safelist.TagName tagName = Safelist.TagName.valueOf(tag);

            if(tagNames.remove(tagName)) { // Only look in sub-maps if tag was allowed
                attributes.remove(tagName);
                enforcedAttributesManager.removeAll(tagName);
                // remove protocols for tag via manager
                Map<Safelist.AttributeKey, Set<Safelist.Protocol>> map = protocolsManager.getProtocolsMap(tagName);
                if (map != null) {
                    for (Safelist.AttributeKey k : new HashSet<>(map.keySet())) {
                        protocolsManager.removeProtocols(tag, k.toString());
                    }
                }
            }
        }
        return this;
    }

    public SafelistTagAttributes addAttributes(String tag, String... attributes) {
        Validate.notEmpty(tag);
        Validate.notNull(attributes);
        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");

        addTags(tag);
        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Set<Safelist.AttributeKey> attributeSet = new HashSet<>();
        for (String key : attributes) {
            Validate.notEmpty(key);
            attributeSet.add(Safelist.AttributeKey.valueOf(key));
        }
        Set<Safelist.AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
        currentSet.addAll(attributeSet);
        return this;
    }

    public SafelistTagAttributes removeAttributes(String tag, String... attributes) {
        Validate.notEmpty(tag);
        Validate.notNull(attributes);
        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");

        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Set<Safelist.AttributeKey> attributeSet = new HashSet<>();
        for (String key : attributes) {
            Validate.notEmpty(key);
            attributeSet.add(Safelist.AttributeKey.valueOf(key));
        }
        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
            Set<Safelist.AttributeKey> currentSet = this.attributes.get(tagName);
            currentSet.removeAll(attributeSet);

            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
                this.attributes.remove(tagName);
        }
        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
            Iterator<Map.Entry<Safelist.TagName, Set<Safelist.AttributeKey>>> it = this.attributes.entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry<Safelist.TagName, Set<Safelist.AttributeKey>> entry = it.next();
                Set<Safelist.AttributeKey> currentSet = entry.getValue();
                currentSet.removeAll(attributeSet);
                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
                    it.remove();
            }
        }
        return this;
    }

    public boolean isSafeTag(String tag) {
        return tagNames.contains(Safelist.TagName.valueOf(tag));
    }

    // package-visible helper for Safelist internals
    Set<Safelist.AttributeKey> getAllowedAttributes(Safelist.TagName tag) {
        return attributes.get(tag);
    }
}

package org.jsoup.safety;

import org.jsoup.helper.ValidationException;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

public class SafelistTest {
    private static final String TEST_TAG = "testTag";
    private static final String TEST_ATTRIBUTE = "testAttribute";
    private static final String TEST_SCHEME = "valid-scheme";
    private static final String TEST_VALUE = TEST_SCHEME + "://testValue";

    @Test
    public void testCopyConstructor_noSideEffectOnTags() {
        Safelist safelist1 = Safelist.none();
        safelist1.tagAttributes.addTags(TEST_TAG);
        Safelist safelist2 = new Safelist(safelist1);
        safelist1.tagAttributes.addTags("invalidTag");

        assertFalse(safelist2.isSafeTag("invalidTag"));
    }

    @Test
    public void testCopyConstructor_noSideEffectOnAttributes() {
        Safelist safelist1 = Safelist.none();
        safelist1.tagAttributes.addAttributes(TEST_TAG, TEST_ATTRIBUTE);
        Safelist safelist2 = new Safelist(safelist1);
        safelist1.tagAttributes.addAttributes(TEST_TAG, "invalidAttribute");

        assertFalse(safelist2.isSafeAttribute(TEST_TAG, null, new Attribute("invalidAttribute", TEST_VALUE)));
    }

    @Test
    public void testCopyConstructor_noSideEffectOnEnforcedAttributes() {
        Safelist safelist1 = Safelist.none().addEnforcedAttribute(TEST_TAG, TEST_ATTRIBUTE, TEST_VALUE);
        Safelist safelist2 = new Safelist(safelist1);
        safelist1.addEnforcedAttribute(TEST_TAG, TEST_ATTRIBUTE, "invalidValue");

        for (Attribute enforcedAttribute : safelist2.getEnforcedAttributes(TEST_TAG)) {
            assertNotEquals("invalidValue", enforcedAttribute.getValue());
        }
    }

    @Test
    public void testCopyConstructor_noSideEffectOnProtocols() {
        final String invalidScheme = "invalid-scheme";
        Safelist safelist1 = Safelist.none();
        safelist1.tagAttributes.addAttributes(TEST_TAG, TEST_ATTRIBUTE);
        safelist1.addProtocols(TEST_TAG, TEST_ATTRIBUTE, TEST_SCHEME);
        Safelist safelist2 = new Safelist(safelist1);
        safelist1.addProtocols(TEST_TAG, TEST_ATTRIBUTE, invalidScheme);

        Attributes attributes = new Attributes();
        Attribute invalidAttribute = new Attribute(TEST_ATTRIBUTE, invalidScheme + "://someValue");
        attributes.put(invalidAttribute);
        Element invalidElement = new Element(Tag.valueOf(TEST_TAG), "", attributes);

